int xc2028_set_config(struct dvb_frontend *fe, void *priv_cfg)
{
    struct xc2028_data *cfg = (struct xc2028_data *)priv_cfg;
    int result = 0;

    mutex_lock(&fe->lock);

    if (fe->ops->release) {
        kfree(fe->ops->release);
    }

    fe->ops->release = kstrdup(cfg->firmware_name, GFP_KERNEL);
    if (!fe->ops->release) {
        mutex_unlock(&fe->lock);
        return -ENOMEM;
    }

    if (strcmp(fe->ops->release, fe->ops->name) != 0) {
        kfree(fe->ops->release);
        fe->ops->release = NULL;
        result = request_firmware_nowait(NULL, true, fe->ops->name, fe->dvb->priv,
                                          GFP_KERNEL, fe, xc2028_firmware_callback);
        if (result < 0) {
            mutex_unlock(&fe->lock);
            return result;
        }
    }

    mutex_unlock(&fe->lock);
    return result;
}

int xc2028_set_config(struct dvb_frontend *fe, void *priv_cfg)
{
    struct xc2028_priv *cfg = (struct xc2028_priv *)priv_cfg;
    int result = 0;

    mutex_lock(&fe->lock);

    if (strcmp(cfg->firmware_name, fe->dtv_property_cache.firmware_name)) {
        if (fe->dtv_property_cache.firmware_name)
            kfree(fe->dtv_property_cache.firmware_name);

        fe->dtv_property_cache.firmware_name = kstrdup(cfg->firmware_name, GFP_KERNEL);
        if (!fe->dtv_property_cache.firmware_name) {
            mutex_unlock(&fe->lock);
            return -ENOMEM;
        }
    }

    if (fe->state == FIRMWARE_REQUESTED) {
        result = request_firmware_nowait(NULL, 0, fe->dtv_property_cache.firmware_name,
                                         &fe->dvb->adapter->dev, GFP_KERNEL,
                                         &xc2028_firmware_cb, fe);
    }

    mutex_unlock(&fe->lock);
    return result;
}

int xc2028_set_config(struct dvb_frontend *fe, void *priv_cfg)
{
    struct xc2028_data *priv = fe->demodulator_priv;
    struct xc2028_config *config = priv_cfg;
    int result = 0;

    mutex_lock(&priv->lock);

    if (strcmp(priv->firmware_name, config->firmware_name) != 0) {
        if (priv->firmware_name) {
            kfree(priv->firmware_name);
        }
        priv->firmware_name = kstrdup(config->firmware_name, GFP_KERNEL);
        if (!priv->firmware_name) {
            mutex_unlock(&priv->lock);
            return -ENOMEM;
        }
    }

    if (priv->state == XC2028_STATE_NO_FW) {
        result = request_firmware_nowait(
            THIS_MODULE, 1, priv->firmware_name,
            &fe->dvb->adapter->dev, GFP_KERNEL, priv, xc2028_fw_callback);
        if (result < 0) {
            mutex_unlock(&priv->lock);
            return result;
        }
    }

    mutex_unlock(&priv->lock);
    return result;
}

int xc2028_set_config(struct dvb_frontend *fe, void *priv_cfg)
{
    struct xc2028_data *cfg = (struct xc2028_data *)priv_cfg;
    int result = 0;

    mutex_lock(&fe->lock);

    if (strcmp(fe->ops.tuner_ops.set_config.firmware_name, cfg->firmware_name) != 0) {
        kfree(fe->ops.tuner_ops.set_config.firmware_name);
        fe->ops.tuner_ops.set_config.firmware_name = kstrdup(cfg->firmware_name, GFP_KERNEL);
        if (!fe->ops.tuner_ops.set_config.firmware_name) {
            mutex_unlock(&fe->lock);
            return -ENOMEM;
        }
    }

    if (fe->state == XC2028_TUNER_IDLE) {
        result = request_firmware_nowait(
            THIS_MODULE,
            false,
            fe->ops.tuner_ops.set_config.firmware_name,
            &fe->dvb->adapter->dev,
            GFP_KERNEL,
            fe,
            xc2028_firmware_cb
        );
        if (result < 0) {
            mutex_unlock(&fe->lock);
            return result;
        }
    }

    memcpy(&fe->ops.tuner_ops.set_config, cfg, sizeof(struct xc2028_data));

    mutex_unlock(&fe->lock);

    return result;
}

int xc2028_set_config(struct dvb_frontend *fe, void *priv_cfg)
{
    struct xc2028_private *cfg = (struct xc2028_private *)priv_cfg;
    int result = 0;

    mutex_lock(&fe->mutex);

    if (cfg->firmware_name && strcmp(cfg->firmware_name, fe->ops->get_firmware(fe))) {
        kfree(fe->priv);
        fe->priv = kstrdup(cfg->firmware_name, GFP_KERNEL);
        if (!fe->priv) {
            mutex_unlock(&fe->mutex);
            return -ENOMEM;
        }
    }

    if (!fe->ops->has_firmware(fe)) {
        result = request_firmware_nowait(
            THIS_MODULE, 1, fe->priv, fe->dvb->adapter->num, fe->dvb,
            NULL, NULL);
        if (result < 0) {
            mutex_unlock(&fe->mutex);
            return result;
        }
    }

    mutex_unlock(&fe->mutex);
    return result;
}
